# Review package: 6122b4fb3d090c761f25b3c88d9a7273406148e0..18f3498

## Commits
18f3498 Add greet function with graceful empty input handling

## Files changed
 greet.js      |  8 ++++++++
 greet.test.js | 32 ++++++++++++++++++++++++++++++++
 2 files changed, 40 insertions(+)

## Diff
diff --git a/greet.js b/greet.js
new file mode 100644
index 0000000..566720c
--- /dev/null
+++ b/greet.js
@@ -0,0 +1,8 @@
+function greet(name) {
+  if (!name || typeof name !== 'string' || name.trim() === '') {
+    return 'Hello, there!';
+  }
+  return `Hello, ${name}!`;
+}
+
+module.exports = { greet };
diff --git a/greet.test.js b/greet.test.js
new file mode 100644
index 0000000..de30093
--- /dev/null
+++ b/greet.test.js
@@ -0,0 +1,32 @@
+const test = require('node:test');
+const assert = require('node:assert');
+const { greet } = require('./greet');
+
+test('greet returns formatted greeting for normal input', () => {
+  assert.strictEqual(greet('Alice'), 'Hello, Alice!');
+  assert.strictEqual(greet('Bob'), 'Hello, Bob!');
+});
+
+test('greet handles empty string gracefully', () => {
+  const result = greet('');
+  assert.strictEqual(typeof result, 'string');
+  assert.ok(result.length > 0, 'Should return a non-empty string');
+});
+
+test('greet handles null gracefully', () => {
+  const result = greet(null);
+  assert.strictEqual(typeof result, 'string');
+  assert.ok(result.length > 0, 'Should return a non-empty string');
+});
+
+test('greet handles undefined gracefully', () => {
+  const result = greet(undefined);
+  assert.strictEqual(typeof result, 'string');
+  assert.ok(result.length > 0, 'Should return a non-empty string');
+});
+
+test('greet handles whitespace-only input', () => {
+  const result = greet('   ');
+  assert.strictEqual(typeof result, 'string');
+  assert.ok(result.length > 0, 'Should return a non-empty string');
+});
